SELECT sys01_ics_check_cycle_type
  FROM sys01_company
 WHERE sys01_company_id = #{companyId}

WITH chkList AS (
SELECT * , ics21_checklist_l_class_nm AS ics10_check_l_class_nm , ics21_seq AS ics10_check_l_class_seq , ics23_checklist_m_class_nm AS ics10_check_m_class_nm , ics23_seq AS ics10_check_m_class_seq FROM ics10_checklist INNER JOIN ics_class ON ics23_checklist_m_class_id = ics10_checklist_m_class_id INNER JOIN ics11_checklist_company ON ( ics11_company_id = #{companyId} AND ics11_checklist_id = ics10_checklist_id ) INNER JOIN sch22_write_group ON sch22_write_group_id = ics11_write_group_id INNER JOIN ( SELECT sch02_info_id , sch02_person_id AS person_id FROM sch02_share WHERE sch02_company_id = #{companyId} AND sch02_share_cd = '1' AND #{stdDate} BETWEEN sch02_start_date AND COALESCE(sch02_close_date,'9999-12-31') UNION SELECT sch02_info_id , emp03_person_id AS person_id FROM emp03_trans INNER JOIN sch02_share ON sch02_org_id = emp03_org_code_id WHERE (emp03_person_id, emp03_trans_date) IN ( SELECT emp03_person_id, MAX(emp03_trans_date) FROM emp03_trans INNER JOIN emp01_person ON emp01_person_id = emp03_person_id WHERE emp01_company_id = #{companyId} AND emp03_trans_date <= #{stdDate} GROUP BY emp03_person_id ) AND sch02_company_id = #{companyId} AND sch02_share_cd = '2' AND #{stdDate} BETWEEN sch02_start_date AND COALESCE(sch02_close_date,'9999-12-31') ) emp ON sch02_info_id = sch22_write_group_id WHERE COALESCE(ics10_use_yn,'false') = 'true' AND COALESCE(ics11_use_yn,'false') = 'true' AND emp.person_id = #{personId} AND NOT EXISTS ( SELECT 1 FROM emp04_add_title WHERE emp04_add_person_id = emp.person_id AND ( ( emp04_start_date > #{stdDate} ) OR COALESCE(emp04_close_date,'9999-12-31') < #{stdDate} ) ) ) SELECT ics10_checklist_id AS checklist_id, ics10_company_id AS company_id, ics10_content AS content, ics10_criterion AS criterion, ics10_seq AS seq, ics10_checklist_m_class_id AS checklist_m_class_id, ics21_checklist_l_class_id AS check_l_class_id, ics10_check_l_class_nm AS check_l_class_name, ics10_check_m_class_nm AS check_m_class_name, ics15_checklist_write_id AS checklist_write_id, ics15_answer_cd AS answer_code, ics15_reason AS reason, COALESCE(ics15_fix_yn,'false') = 'true' AS fix_yn, COALESCE(ics15_confirm_yn,'false') = 'true' AS confirm_yn FROM chkList LEFT OUTER JOIN ics15_checklist_write ON ( ics15_checklist_id = ics10_checklist_id AND ics15_company_id = #{companyId} AND ics15_person_id = person_id AND ics15_cycle_type = #{cycleType} AND ics15_check_yyyymm = TO_CHAR(#{stdDate}::date,'YYYY.MM') ) WHERE 1=1 AND COALESCE(ics24_use_yn, ics23_use_yn) = 'true' AND COALESCE(ics22_use_yn, ics21_use_yn) = 'true'
AND ics21_checklist_l_class_id = #{checklistLClassId}
AND ics23_checklist_m_class_id = #{checklistMClassId}
AND ics15_answer_cd IS NULL
AND CONCAT(ics10_check_l_class_nm, ics10_check_m_class_nm, ics10_content) LIKE #{searchText} ORDER BY ics10_check_l_class_seq, ics10_check_m_class_seq, ics10_seq, ics10_content

SELECT ics15_checklist_write_id                    AS checklist_write_id,
       ics15_checklist_id                          AS checklist_id,
       ics15_answer_cd                             AS answer_code,
       ics15_reason                                AS reason,
       COALESCE(ics15_fix_yn,'false') = 'true'     AS fix_yn,
       COALESCE(ics15_confirm_yn,'false') = 'true' AS confirm_yn
  FROM ics15_checklist_write
 WHERE ics15_checklist_write_id = #{checklistWriteId}
   AND ics15_company_id = #{companyId}
   AND ics15_person_id  = #{personId}

SELECT ics15_checklist_write_id                    AS checklist_write_id,
       ics15_checklist_id                          AS checklist_id,
       ics15_answer_cd                             AS answer_code,
       ics15_reason                                AS reason,
       COALESCE(ics15_fix_yn,'false') = 'true'     AS fix_yn,
       COALESCE(ics15_confirm_yn,'false') = 'true' AS confirm_yn
  FROM ics15_checklist_write
 WHERE ics15_company_id   = #{companyId}
   AND ics15_checklist_id = #{checklistId}
   AND ics15_person_id    = #{personId}
   AND ics15_check_yyyymm = #{yyyymm}
   AND ics15_cycle_type   = #{cycleType}
 ORDER BY ics15_checklist_write_id

